reference.code:
def dispatch_status(minutes, available, connected, maintenance):
    if minutes <= 0:
        return "invalid"
    if maintenance:
        return "maintenance"
    if not connected:
        return "offline"
    if minutes > available:
        return "over budget"
    return "ready"

print(dispatch_status(20, 20, True, False))
